===== src/service/EarnPolicy.java
     1	package service;
     2	
     3	import domain.Grade;
     4	
     5	/** Points for one payment: grade rate in basis points, rounded down, capped per payment. */
     6	public final class EarnPolicy {
     7	    private final long capPerPayment;
     8	
     9	    public EarnPolicy(long capPerPayment) {
    10	        this.capPerPayment = capPerPayment;
    11	    }
    12	
    13	    public long points(long amount, Grade grade) {
    14	        if (amount <= 0) return 0;
    15	        long raw = Math.floorDiv(Math.multiplyExact(amount, (long) grade.bps()), 10_000L);
    16	        return Math.min(raw, capPerPayment);
    17	    }
    18	}
===== src/service/PaymentDeduper.java
     1	package service;
     2	
     3	import domain.Payment;
     4	
     5	import java.util.ArrayList;
     6	import java.util.LinkedHashSet;
     7	import java.util.List;
     8	import java.util.Set;
     9	
    10	/** The acquirer resends rows after a timeout; the same payment id must be counted once. */
    11	public final class PaymentDeduper {
    12	    private PaymentDeduper() {}
    13	
    14	    public static List<Payment> unique(List<Payment> payments) {
    15	        Set<String> seen = new LinkedHashSet<>();
    16	        List<Payment> out = new ArrayList<>();
    17	        for (Payment p : payments) {
    18	            if (seen.add(p.payId())) out.add(p);
    19	        }
    20	        return out;
    21	    }
    22	}
===== src/store/EarnLedger.java
     1	package store;
     2	
     3	import domain.EarnEntry;
     4	
     5	import java.time.YearMonth;
     6	import java.util.ArrayList;
     7	import java.util.LinkedHashMap;
     8	import java.util.List;
     9	import java.util.Map;
    10	
    11	/** Our own record of earns already sent, keyed by payment id (a payment earns once). */
    12	public class EarnLedger {
    13	    private final Map<String, EarnEntry> byPayment = new LinkedHashMap<>();
    14	
    15	    public synchronized boolean contains(String payId) {
    16	        return byPayment.containsKey(payId);
    17	    }
    18	
    19	    public synchronized void record(EarnEntry e) {
    20	        byPayment.put(e.payId(), e);
    21	    }
    22	
    23	    public synchronized List<EarnEntry> all() {
    24	        return new ArrayList<>(byPayment.values());
    25	    }
    26	
    27	    public synchronized long earnedIn(String memberNo, YearMonth month) {
    28	        return byPayment.values().stream()
    29	                .filter(e -> e.memberNo().equals(memberNo) && YearMonth.from(e.day()).equals(month))
    30	                .mapToLong(EarnEntry::points).sum();
    31	    }
    32	}

