    11	/** Our own record of earns already sent, keyed by payment id (a payment earns once). */
    12	public class EarnLedger {
    13	    private final Map<String, EarnEntry> byPayment = new LinkedHashMap<>();
    14	
    15	    public synchronized boolean contains(String payId) {
    16	        return byPayment.containsKey(payId);
    17	    }
    18	
    19	    public synchronized void record(EarnEntry e) {
    20	        byPayment.put(e.payId(), e);
    21	    }
    22	
    23	    public synchronized List<EarnEntry> all() {
    24	        return new ArrayList<>(byPayment.values());
    25	    }
    26	
    27	    public synchronized long earnedIn(String memberNo, YearMonth month) {
    28	        return byPayment.values().stream()
    29	                .filter(e -> e.memberNo().equals(memberNo) && YearMonth.from(e.day()).equals(month))
    30	                .mapToLong(EarnEntry::points).sum();
    31	    }
    32	}

