===== src/service/TopEarnersReport.java
     1	package service;
     2	
     3	import domain.EarnEntry;
     4	import domain.Member;
     5	import store.EarnLedger;
     6	
     7	import java.time.YearMonth;
     8	import java.util.ArrayList;
     9	import java.util.Comparator;
    10	import java.util.LinkedHashMap;
    11	import java.util.List;
    12	import java.util.Map;
    13	
    14	/** Marketing's monthly "top earners" list, from what we sent to the vendor this month. */
    15	public class TopEarnersReport {
    16	    public record Row(String memberNo, String name, long points) {}
    17	
    18	    private final MemberDirectory members;
    19	    private final EarnLedger ledger;
    20	
    21	    public TopEarnersReport(MemberDirectory members, EarnLedger ledger) {
    22	        this.members = members;
    23	        this.ledger = ledger;
    24	    }
    25	
    26	    public List<Row> top(YearMonth month, int n) {
    27	        Map<String, Long> sums = new LinkedHashMap<>();
    28	        for (EarnEntry e : ledger.all()) {
    29	            if (YearMonth.from(e.day()).equals(month)) sums.merge(e.memberNo(), e.points(), Long::sum);
    30	        }
    31	        List<Row> rows = new ArrayList<>();
    32	        for (Map.Entry<String, Long> s : sums.entrySet()) {
    33	            String name = members.find(s.getKey()).map(Member::name).orElse("?");
    34	            rows.add(new Row(s.getKey(), name, s.getValue()));
    35	        }
    36	        rows.sort(Comparator.comparingLong(Row::points).reversed().thenComparing(Row::memberNo));
    37	        return rows.size() > n ? rows.subList(0, n) : rows;
    38	    }
    39	}
